  1	import { createStep, createWorkflow } from '@mastra/core/workflows';
  2	import { z } from 'zod';
  3	import { PARTIAL_DATE, VOICES } from '#lib/types.ts';
  4	import type { Candidate, Inscription, SourceRecord } from '#lib/types.ts';
  5	import { ProviderError, runFailure } from './http.ts';
  6	import { dropGated, resolveMatches, searchPhases } from './identity.ts';
  7	import type { SearchHit } from './search/index.ts';
  8	import { search } from './search/serpapi.ts';
  9	import { canonicalUrl } from './search/url.ts';
 10	
 11	export const confidenceSchema = z.enum(['high', 'medium', 'low']);
 12	
 13	export const partialDate = z.string().regex(PARTIAL_DATE);
 14	
 15	export const inscriptionSchema = z.object({
 16		carvedName: z.string(),
 17		name: z.string().min(1),
 18		maidenName: z.string().nullable(),
 19		born: partialDate.nullable(),
 20		died: partialDate.nullable(),
 21		voice: z.enum(VOICES).nullable(),
 22		place: z.string().max(120).nullable()
 23	});
 24	
 25	export const sourceSchema = z.object({
 26		id: z.string(),
 27		url: z.string().regex(/^https?:\/\//i),
 28		title: z.string(),
 29		site: z.string(),
 30		snippet: z.string()
 31	});
 32	
 33	export const candidateSchema = z.object({
 34		name: z.string(),
 35		born: partialDate.nullable(),
 36		died: partialDate.nullable(),
 37		confidence: confidenceSchema,
 38		sources: z.array(sourceSchema)
 39	});
 40	
 41	const candidatesSchema = z.object({ candidates: z.array(candidateSchema) });
 42	
 43	const RETRIES = 2;
 44	
 45	const attemptSchema = z.object({ query: z.string(), engine: z.string(), phase: z.number() });
 46	// Where a page first turned up: its phase, and its rank among that phase's results.
 47	const foundSchema = sourceSchema.extend({ phase: z.number(), rank: z.number() });
 48	type Found = z.infer<typeof foundSchema>;
 49	const searchStateSchema = z.object({
 50		inscription: inscriptionSchema,
 51		pending: z.array(attemptSchema),
 52		tried: z.number(),
 53		failed: z.number(),
 54		records: z.array(foundSchema),
 55		candidates: z.array(candidateSchema)
 56	});
 57	type SearchState = z.infer<typeof searchStateSchema>;
 58	
 59	/**
 60	 * Tells whether any candidate matched more than the name.
 61	 * @param candidates Resolved candidates.
 62	 * @returns True when one is high or medium confidence.
 63	 */
 64	const dated = (candidates: Candidate[]) => candidates.some((c) => c.confidence !== 'low');
 65	
 66	/**
 67	 * Adds hits to the records found so far, numbering new pages and folding a repeat page's snippet into
 68	 * its record.
 69	 * @param records Records found so far.
 70	 * @param hits New hits in rank order.
 71	 * @param phase The phase that ran the search.
 72	 * @returns The combined records.
 73	 */
 74	function addHits(records: Found[], hits: SearchHit[], phase: number): Found[] {
 75		const out = [...records];
 76		let rank = out.filter((r) => r.phase === phase).length;
 77		for (const hit of hits) {
 78			const key = canonicalUrl(hit.url);
 79			const i = out.findIndex((r) => canonicalUrl(r.url) === key);
 80			if (i < 0) out.push({ id: `s${out.length + 1}`, ...hit, phase, rank: rank++ });
 81			// Another query can show the same page with the dates in its snippet.
 82			else if (!out[i].snippet.includes(hit.snippet))
 83				out[i] = { ...out[i], snippet: `${out[i].snippet} … ${hit.snippet}` };
 84		}
 85		return out;
 86	}
 87	
 88	/**
 89	 * Orders records so every phase's best results come before any phase's next ones.
 90	 * @param records Records found so far.
 91	 * @returns Plain records, interleaved by rank across phases.
 92	 */
 93	function interleave(records: Found[]): SourceRecord[] {
 94		// Matching keeps five sources in this order. Appended in search order, the first phase's
 95		// namesakes filled all five, and pages from later phases were never fetched.
 96		return [...records]
 97			.sort((a, b) => a.rank - b.rank || a.phase - b.phase)
 98			.map((r) => sourceSchema.parse(r));
 99	}
100	
101	const planStep = createStep({
102		id: 'plan',
103		inputSchema: inscriptionSchema,
104		outputSchema: searchStateSchema,
105		execute: ({ inputData }) =>
106			Promise.resolve({
107				inscription: inputData,
108				// Each phase tries the first engine, and the next only when that one misses.
109				pending: searchPhases(inputData).flatMap((query, phase) =>
110					search.engines.map((engine) => ({ query, engine, phase }))
111				),
112				tried: 0,
113				failed: 0,
114				records: [],
115				candidates: []
116			})
117	});
118	
119	const searchStep = createStep({
120		id: 'search',
121		inputSchema: searchStateSchema,
122		outputSchema: searchStateSchema,
123		retries: RETRIES,
124		execute: async ({ inputData, retryCount }): Promise<SearchState> => {
125			const [next, ...pending] = inputData.pending;
126			let hits: SearchHit[] = [];
127			let failed = inputData.failed;
128			try {
129				hits = await search.search(next.query, next.engine);
130			} catch (e) {
131				// Mastra retries the step first; an engine still failing after that counts as a miss.
132				if (retryCount < RETRIES) throw e;
133				failed++;
134			}
135			const records = addHits(inputData.records, hits, next.phase);
136			return {
137				...inputData,
138				pending,
139				tried: inputData.tried + 1,
140				failed,
141				records,
142				candidates: resolveMatches(inputData.inscription, dropGated(interleave(records)))
143			};
144		}
145	});
146	
147	const resolveStep = createStep({
148		id: 'resolve',
149		inputSchema: searchStateSchema,
150		outputSchema: candidatesSchema,
151		execute: ({ inputData }) => {
152			if (inputData.failed === inputData.tried) {
153				throw new ProviderError('Search failed on every engine');
154			}
155			return Promise.resolve({ candidates: inputData.candidates });
156		}
157	});
158	
159	const researchWorkflow = createWorkflow({
160		id: 'research',
161		inputSchema: inscriptionSchema,
162		outputSchema: candidatesSchema
163	})
164		.then(planStep)
165		// Stop at the first dated match: every further search costs a SerpApi credit.
166		.dountil(
167			searchStep,
168			async ({ inputData: s }) =>
169				dated(s.candidates) ||
170				!s.pending.length ||
171				// Every engine failing on the first phase is an outage, not a miss.
172				(s.failed === s.tried && s.tried >= search.engines.length)
173		)
174		.then(resolveStep)
175		.commit();
176	
177	/**
178	 * Searches for records about a stone's person and keeps the ones that match.
179	 * @param inscription The stone's person.
180	 * @returns Candidates, possibly empty.
181	 * @throws {ProviderError} When search fails after retries.
182	 */
183	export async function runResearch(inscription: Inscription): Promise<Candidate[]> {
184		const run = await researchWorkflow.createRun();
185		const result = await run.start({ inputData: inscription });
186		if (result.status !== 'success') {
187			throw runFailure('Research', result.status === 'failed' ? result.error : undefined);
188		}
189		return result.result.candidates;
190	}
  1	import { serpApiKey } from '../env.ts';
  2	import type { SearchHit, SearchProvider } from './index.ts';
  3	import { ENGINES, type Engine } from './engines.ts';
  4	import { canonicalUrl } from './url.ts';
  5	
  6	interface OrganicResult {
  7		link?: string;
  8		title?: string;
  9		snippet?: string;
 10	}
 11	
 12	// Bidi embedding, override and isolate controls can make a source title read differently on screen.
 13	const BIDI = /[\u202a-\u202e\u2066-\u2069]/g;
 14	
 15	/**
 16	 * Removes bidirectional control characters from result text.
 17	 * @param text Title or snippet from a search result.
 18	 * @returns The text without them.
 19	 */
 20	const plain = (text = '') => text.replaceAll(BIDI, '');
 21	
 22	// Fewer page links than this makes a search too thin to skip the redirect hop.
 23	const MIN_LINKS = 3;
 24	
 25	/**
 26	 * Follows one redirect link to the page it leads to.
 27	 * @param origin Origin that serves the engine's redirects.
 28	 * @param link Result link on that origin, relative or absolute.
 29	 * @returns The page URL, or null when the link does not redirect.
 30	 */
 31	async function follow(origin: string, link: string): Promise<string | null> {
 32		try {
 33			const res = await fetch(new URL(link, origin), {
 34				redirect: 'manual',
 35				signal: AbortSignal.timeout(5_000)
 36			});
 37			return res.headers.get('location');
 38		} catch {
 39			// A redirect that fails costs only that result, the same as a link that never resolved.
 40			return null;
 41		}
 42	}
 43	
 44	/**
 45	 * Runs one engine through SerpApi.
 46	 * @param e Engine settings.
 47	 * @param query Search query.
 48	 * @returns The engine's organic results; none when it reports an empty result set.
 49	 * @throws {Error} When the request fails.
 50	 */
 51	async function searchEngine(e: Engine, query: string): Promise<OrganicResult[]> {
 52		const url = new URL('https://serpapi.com/search.json');
 53		url.search = new URLSearchParams({
 54			engine: e.engine,
 55			[e.queryParam]: query,
 56			...e.extra,
 57			api_key: serpApiKey()
 58		}).toString();
 59		const res = await fetch(url, { signal: AbortSignal.timeout(20_000) });
 60		const body: { organic_results?: OrganicResult[]; error?: string } = await res.json();
 61		// SerpApi reports an empty result set as an error string.
 62		if (body.error?.includes("hasn't returned any results")) return [];
 63		if (!res.ok || body.error) throw new Error(body.error ?? `SerpApi ${res.status}`);
 64		return body.organic_results ?? [];
 65	}
 66	
 67	/** Web search through SerpApi, one engine per call. */
 68	export class SerpApiProvider implements SearchProvider {
 69		readonly engines = ENGINES.map((e) => e.engine);
 70	
 71		/** @inheritdoc */
 72		async search(query: string, engine: string): Promise<SearchHit[]> {
 73			const e = ENGINES.find((x) => x.engine === engine);
 74			if (!e) throw new Error(`Unknown engine ${engine}`);
 75			const results = await searchEngine(e, query);
 76			const { redirects } = e;
 77			// A link on the engine's redirect origin, relative or absolute, is a hop and never a page.
 78			const hops = results.map(
 79				(r) => !!redirects && !!r.link && URL.parse(r.link, redirects)?.origin === redirects
 80			);
 81			let links = results.map((r, i) => (r.link && !hops[i] && canonicalUrl(r.link) ? r.link : null));
 82			if (redirects && links.filter(Boolean).length < MIN_LINKS)
 83				links = await Promise.all(
 84					results.map((r, i) => (hops[i] ? follow(redirects, r.link!) : links[i]))
 85				);
 86			return results.flatMap((r, i) => {
 87				const url = links[i];
 88				return url && canonicalUrl(url)
 89					? [
 90							{
 91								url,
 92								title: plain(r.title),
 93								site: URL.parse(url)!.hostname,
 94								snippet: plain(r.snippet)
 95							}
 96						]
 97					: [];
 98			});
 99		}
100	}
101	
102	export const search: SearchProvider = new SerpApiProvider();
  1	export interface Engine {
  2		engine: string;
  3		/** SerpApi names the query parameter differently per engine. */
  4		queryParam: string;
  5		extra?: Record<string, string>;
  6		/** Origin that answers the engine's relative result links with a redirect to the page. */
  7		redirects?: string;
  8	}
  9	
 10	/**
 11	 * Engines that return organic results as link, title and snippet, in the order research tries them.
 12	 * Kept after benchmarks/results/search-1.json: Google and Yandex found 31 of the 35 kept sources and
 13	 * 29 of the 31 found by one engine only. Yahoo added little at the slowest speed of the three, Bing
 14	 * returned 94 results and no match, and DuckDuckGo returned one result in ten stones.
 15	 * Yandex leads after research-1.json: Google returned 0 to 3 results per query against Yandex's 1 to
 16	 * 14, and never found a dated match on a query without a town.
 17	 */
 18	export const ENGINES: Engine[] = [
 19		{ engine: 'yandex', queryParam: 'text' },
 20		{
 21			engine: 'google',
 22			queryParam: 'q',
 23			extra: { num: '10', gl: 'us', hl: 'en' },
 24			// Since October 2026 Google links most results through /goto, which SerpApi passes on as-is.
 25			redirects: 'https://www.google.com'
 26		}
 27	];
