  2	
  3	/** A search hit before it is numbered into a research run. */
  4	export type SearchHit = Omit<SourceRecord, 'id'>;
  5	
  6	/** Historical search seam. */
  7	export interface SearchProvider {
  8		/** Engines in the order to try them; a later one runs only when the earlier ones miss. */
  9		readonly engines: readonly string[];
 10		/**
 11		 * Runs one web search on one engine.
 12		 * @param query Search query.
 13		 * @param engine One of `engines`.
 14		 * @returns Hits in the engine's rank order.
 15		 * @throws {Error} When the request fails.
 16		 */
 17		search(query: string, engine: string): Promise<SearchHit[]>;
 18	}

