 30	 */
 31	async function follow(origin: string, link: string): Promise<string | null> {
 32		try {
 33			const res = await fetch(new URL(link, origin), {
 34				redirect: 'manual',
 35				signal: AbortSignal.timeout(5_000)
 36			});
 37			return res.headers.get('location');
 38		} catch {
