 46	 * @param e Engine settings.
 47	 * @param query Search query.
 48	 * @returns The engine's organic results; none when it reports an empty result set.
 49	 * @throws {Error} When the request fails.
 50	 */
 51	async function searchEngine(e: Engine, query: string): Promise<OrganicResult[]> {
 52		const url = new URL('https://serpapi.com/search.json');
 53		url.search = new URLSearchParams({
 54			engine: e.engine,
 55			[e.queryParam]: query,
 56			...e.extra,
 57			api_key: serpApiKey()
 58		}).toString();
 59		const res = await fetch(url, { signal: AbortSignal.timeout(20_000) });
 60		const body: { organic_results?: OrganicResult[]; error?: string } = await res.json();
 61		// SerpApi reports an empty result set as an error string.
 62		if (body.error?.includes("hasn't returned any results")) return [];
 63		if (!res.ok || body.error) throw new Error(body.error ?? `SerpApi ${res.status}`);
 64		return body.organic_results ?? [];
 65	}
