 67	/** Web search through SerpApi, one engine per call. */
 68	export class SerpApiProvider implements SearchProvider {
 69		readonly engines = ENGINES.map((e) => e.engine);
 70	
 71		/** @inheritdoc */
 72		async search(query: string, engine: string): Promise<SearchHit[]> {
 73			const e = ENGINES.find((x) => x.engine === engine);
 74			if (!e) throw new Error(`Unknown engine ${engine}`);
 75			const results = await searchEngine(e, query);
 76			const { redirects } = e;
 77			// A link on the engine's redirect origin, relative or absolute, is a hop and never a page.
 78			const hops = results.map(
 79				(r) => !!redirects && !!r.link && URL.parse(r.link, redirects)?.origin === redirects
 80			);
 81			let links = results.map((r, i) => (r.link && !hops[i] && canonicalUrl(r.link) ? r.link : null));
 82			if (redirects && links.filter(Boolean).length < MIN_LINKS)
 83				links = await Promise.all(
 84					results.map((r, i) => (hops[i] ? follow(redirects, r.link!) : links[i]))
 85				);
 86			return results.flatMap((r, i) => {
 87				const url = links[i];
 88				return url && canonicalUrl(url)
 89					? [
 90							{
 91								url,
 92								title: plain(r.title),
 93								site: URL.parse(url)!.hostname,
 94								snippet: plain(r.snippet)
 95							}
 96						]
 97					: [];
 98			});
 99		}
100	}
