92		// Unquoted, so an obituary naming the town in other words still ranks. Lowercase, so a carved
93		// "OR" can't act as a search operator.
94		const place = inscription.place
95			?.toLowerCase()
96			.replace(/[^\p{L}\p{N}' -]+/gu, ' ')
97			.replace(/\s+/g, ' ')
98			.trim();
99		return [exactName(inscription), ...yearsOf(inscription), place].filter(Boolean).join(' ');
100	}
101	
102	/**
103	 * Lists the research queries for a stone, tightest first: name and dates, then with the town,
104	 * then name and town without the dates; each plain, then with death keywords.
105	 * @param inscription The stone's person.
106	 * @returns Distinct queries in the order to try them.
107	 */
108	export function searchPhases(inscription: Inscription): string[] {
109		// Dates lead: adding the town first hid dates from records the bare search already matched.
110		const queries = [
111			buildQuery({ ...inscription, place: null }),
112			buildQuery(inscription),
113			// A name-only search returns namesakes the story would reject, so it is never a phase.
114			inscription.place ? buildQuery({ ...inscription, born: null, died: null }) : null
115		];
116		// Each phase asks without death keywords first, which finds pages about the life and some
117		// memorials, then with them, which finds obituaries the plain query ranks lower.
118		return [
119			...new Set(
120				queries.filter((q) => q !== null).flatMap((q) => [q, `${q} (obituary OR grave OR cemetery)`])
121			)
122		];
123	}
124	
125	/**
126	 * Removes records from paywalled or login-gated genealogy sites and people-search directories.
127	 * @param records Search hits.
128	 * @returns Hits on open sites that can hold a record of the dead.
129	 */
130	export function dropGated(records: SourceRecord[]): SourceRecord[] {
131		return records.filter((r) => {
132			const site = r.site.toLowerCase();
133			return !GATED.test(site) && !DIRECTORIES.test(site);
134		});
135	}
136	
137	/**
138	 * Lowercases text and folds accents so "Ødegård" and "odegard" compare equal.
139	 * @param text Text to fold.
140	 * @returns Folded text.
141	 */
142	function fold(text: string): string {
143		const letters: Record<string, string> = { æ: 'ae', œ: 'oe', ø: 'o', ß: 'ss', đ: 'd', ł: 'l' };
144		return text
145			.normalize('NFD')
146			.replace(/\p{M}+/gu, '')
147			.toLowerCase()
148			.replace(/[æœøßđł]/g, (c) => letters[c]);
149	}
150	
151	/**
152	 * Splits a name into given names and a surname, ignoring generational suffixes.
153	 * @param name Full name.
154	 * @returns Folded given-name tokens and surname.
155	 */
156	function nameParts(name: string): { given: string[]; surname: string } {
157		// A quoted nickname (Corwin "Cory" Chambers) is another given name a record may use.
158		const parts = fold(name)
159			.replace(/[.,"“”]/g, ' ')
160			.split(/\s+/)
161			.filter(Boolean);
162		while (parts.length > 1 && NAME_SUFFIXES.has(parts.at(-1)!)) parts.pop();
163		const surname = parts.pop() ?? '';
164		return { given: parts, surname };
165	}
166	
167	/**
168	 * Finds every whole-word occurrence of a word.
169	 * @param text Folded text.
170	 * @param word Folded word.
171	 * @returns Indexes of the occurrences.
172	 */
173	function wordIndexes(text: string, word: string): number[] {
174		if (!word) return [];
175		const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
176		const found = text.matchAll(
177			new RegExp(String.raw`(?<![\p{L}\p{N}])${escaped}(?![\p{L}\p{N}])`, 'gu')
178		);
179		return [...found].map((m) => m.index);
180	}
181	
182	/**
183	 * Splits text into words at whitespace, quotes and parentheses, so "Gaynor (Staples) Hawks" reads as one name.
184	 * @param chunk Text to split.
185	 * @param offset Index of the chunk within the full text.
186	 * @returns Words with their index in the full text.
187	 */
188	function wordsOf(chunk: string, offset: number): { word: string; index: number }[] {
189		return [...chunk.matchAll(/[^\s"“”()]+/gu)].map((m) => ({ word: m[0], index: offset + m.index }));
190	}
191	
192	/**
193	 * Classifies a word as part of a personal name.
194	 * @param word A word from the text.
195	 * @returns The bare name, and whether trailing punctuation ends the name; null for other words.
196	 */
197	function namePart(word: string): { name: string; closes: boolean } | null {
198		const name = word.replace(/[.,]$/, '');
199		if (!NAME_WORD.test(name)) return null;
200		return { name, closes: name !== word && !(word.endsWith('.') && name.length === 1) };
201	}
202	
203	/**
204	 * Tells whether a word from a record can be one of the stone's given names.
205	 * @param given Folded given names of the stone; an initial stands for any name that starts with it
206	 *   when the stone spells out no given name.
207	 * @param word Folded word from the record.
208	 * @returns True for an exact match, or a name that fits a stone carrying initials only.
209	 */
210	function isGiven(given: string[], word: string): boolean {
211		// Once the stone spells out a name, an initial alone is too weak: "Thai DelRay Hiatt" for Georgia D.
212		const full = given.filter((g) => g.length > 1);
213		return full.length ? full.includes(word) : given.some((g) => g === word || word.startsWith(g));
214	}
215	
216	/**
217	 * Finds where the name phrase containing a surname starts, if a given name is in that phrase.
218	 * @param text Folded text.
219	 * @param given Folded given names of the stone.
220	 * @param at Index of the surname occurrence.
221	 * @param length Length of the surname.
222	 * @returns Index where the phrase starts, -1 when no given name sits in the same phrase, or
223	 *   NAMESAKE when the phrase carries a middle initial the stone's names rule out.
224	 */
225	function phraseStart(text: string, given: string[], at: number, length: number): number {
226		if (!given.length) return at;
227		const from = Math.max(0, at - NAME_REACH);
228		let first = at;
229		let hit = false;
230		let otherInitial = false;
231		for (const w of wordsOf(text.slice(from, at), from).reverse().slice(0, NAME_WORDS_MAX)) {
232			const part = namePart(w.word);
233			// Checked before the prefix words, which hold "a": "Daisy A. Morgan" is not Daisy M. Morgan.
234			if (part?.name.length === 1 && w.word.endsWith('.')) {
235				otherInitial ||= !given.some((g) => g.startsWith(part.name));
236			} else if (!part || part.closes || PREFIX_WORDS.has(part.name)) break;
237			first = w.index;
238			hit ||= isGiven(given, part.name);
239		}
240		if (hit) return otherInitial ? NAMESAKE : first;
241		// "Surname, Given" counts only when the surname opens its phrase; otherwise
242		// "Charles Hawks, Gaynor Jones" would pair Hawks with Gaynor.
243		if (first !== at || text[at + length] !== ',') return -1;
244		const next = at + length + 1;
245		for (const w of wordsOf(text.slice(next, next + NAME_REACH), next).slice(0, NAME_WORDS_MAX - 1)) {
246			const part = namePart(w.word);
247			if (!part) break;
248			if (isGiven(given, part.name)) return at;
249			if (part.closes) break;
250		}
251		return -1;
252	}
253	
254	/**
255	 * Lists the years a result allows that agree with a stone year, where `?` matches any digit.
256	 * @param stone Stone year, possibly with `?` digits.
257	 * @param found Latest year the result allows.
258	 * @param slack Years the true year may lie before `found`, for years derived from an age.
259	 * @returns Agreeing years; empty when none can denote the same year.
260	 */
261	function agreeingYears(stone: string, found: number, slack = 0): number[] {
262		const years: number[] = [];
263		for (let y = found - slack; y <= found; y++) {
264			if ([...stone].every((c, i) => c === '?' || c === String(y)[i])) years.push(y);
265		}
266		return years;
267	}
268	
269	/**
270	 * Finds the year that follows a cue word such as "born" or "died".
271	 * @param text Folded text.
272	 * @param cue Regular-expression source for the cue words.
273	 * @returns The year, or null.
274	 */
275	function labelledYear(text: string, cue: string): number | null {
276		const found = new RegExp(
277			String.raw`(?:${cue})(?:(?!${LIFE_CUE})[^.\d]){0,60}?${DATE_LEAD}\b${YEAR}\b`
278		).exec(text);
279		return found ? +found[1] : null;
280	}
281	
282	/**
283	 * Compares a year the result states with the stone's date for the same key.
284	 * @param stone The stone's date, or null when it carries none.
285	 * @param found The year the result states, or null.
286	 * @param slack Years of tolerance, for years derived from an age.
287	 * @returns "none" when either side is missing, else whether they agree.
288	 */
289	function compareYear(stone: string | null, found: number | null, slack: number): KeyState {
290		if (!stone || found === null) return 'none';
291		return agreeingYears(stone.slice(0, 4), found, slack).length ? 'match' : 'conflict';
292	}
293	
294	/**
295	 * Reads the birth and death years a text states, by label, range or age.
296	 * @param text Folded text around the name.
297	 * @param own The part of that text that belongs to the matched name, where a range is read from.
298	 * @returns Stated years; `bornSlack` is 1 when the birth year was derived from an age, which
299	 *   puts the true year in [born - 1, born].
300	 */
301	function statedYears(
302		text: string,
303		own: string
304	): {
305		born: number | null;
306		died: number | null;
307		bornSlack: number;
308	} {
309		let born: number | null = null;
310		let died: number | null = null;
311		let bornSlack = 0;
312		const range = new RegExp(
313			String.raw`${FULL_DATE_LEAD}\b${YEAR}\s*(?:-|–|—|to)\s*${FULL_DATE_LEAD}\b${YEAR}\b`
314		).exec(own);
315		if (range && +range[2] >= +range[1]) {
316			born = +range[1];
317			died = +range[2];
318		}
319		born ??= labelledYear(text, String.raw`\bborn\b|\bb\.`);
320		died ??= labelledYear(text, DIED_CUE);
321		// "age 85" or the obituary form "Troy Juntunen, 45, of Richland".
322		const age = /\baged?\s+(\d{1,3})\b|,\s*(\d{1,3}),/.exec(text);
323		if (born === null && died !== null && age) {
324			born = died - +(age[1] ?? age[2]);
325			bornSlack = 1;
326		}
327		return { born, died, bornSlack };
328	}
329	
330	/**
331	 * Picks the year to report for a year a result states.
332	 * @param stone The stone's date for the same key, or null.
333	 * @param found The year the result states, or null.
334	 * @param slack Years the true year may lie before `found`, for years derived from an age.
335	 * @returns The stated year; a derived year only when the stone singles out one year of it.
336	 */
337	function reportedYear(stone: string | null, found: number | null, slack: number): string | null {
338		if (found === null) return null;
339		if (slack === 0) return String(found);
340		const agreeing = stone ? agreeingYears(stone.slice(0, 4), found, slack) : [];
341		return agreeing.length === 1 ? String(agreeing[0]) : null;
342	}
343	
344	/**
345	 * Finds the sentence that holds a position, so dates that belong to another person in a later
346	 * sentence ("Her husband John Smith died 2010.") are not read as the matched name's.
347	 * @param text Folded text.
348	 * @param at Index of the matched name.
349	 * @returns The whole sentence, and the part of it from the name onward.
350	 */
351	function sentenceAt(text: string, at: number): { whole: string; fromName: string } {
352		const spans: [number, number][] = [];
353		let from = 0;
354		for (const m of text.matchAll(SENTENCE_END)) {
355			spans.push([from, m.index]);
356			from = m.index + m[0].length;
357		}
358		spans.push([from, text.length]);
359		const first = Math.max(
360			0,
361			spans.findIndex(([, end]) => at <= end)
362		);
363		let last = first;
364		// "Born 1932. Died in 2010." carries on about the same person; "Her husband John died 2010." does not.
365		while (last + 1 < spans.length && CONTINUES.test(text.slice(...spans[last + 1]))) last++;
366		const end = spans[last][1];
367		return { whole: text.slice(spans[first][0], end), fromName: text.slice(at, end) };
368	}
369	
370	/**
371	 * Weighs one search result against the stone, key by key. A key the result does not state is
372	 * neutral; only a stated year that disagrees counts against it.
373	 * @param inscription The stone's person.
374	 * @param record One search result.
375	 * @returns The result's evidence for name, birth year and death year.
376	 */
377	function weigh(inscription: Inscription, record: SourceRecord): Evidence {
378		const text = fold(`${record.title}\n${record.snippet}`);
379		const { given, surname } = nameParts(inscription.name);
380		const maiden = inscription.maidenName ? fold(inscription.maidenName) : null;
381		const none: Evidence = {
382			name: false,
383			born: 'none',
384			died: 'none',
385			bornYear: null,
386			diedYear: null,
387			stated: { born: null, died: null, slack: 0 },
388			statesOther: false
389		};
390	
391		// A page titled with other life dates is someone else's, even when it lists the stone's person
392		// among their kin.
393		const title = fold(record.title);
394		const titled = statedYears(title, title);
395		if (
396			compareYear(inscription.born, titled.born, titled.bornSlack) === 'conflict' ||
397			compareYear(inscription.died, titled.died, 0) === 'conflict'
398		)
399			return none;
400	
401		// The surname, or the maiden name, must share one name phrase with a given name.
402		const found = [surname, maiden].flatMap((n) =>
403			n ? wordIndexes(text, n).map((i) => phraseStart(text, given, i, n.length)) : []
404		);
405		if (found.includes(NAMESAKE)) return none;
406		const starts = found.filter((i) => i >= 0);
407		if (!starts.length) return none;
408	
409		const sentences = starts.map((i) => sentenceAt(text, i));
410		// A range is read from the name onward; a labelled year or an age from the whole sentence.
411		const stated = statedYears(
412			sentences.map((x) => x.whole).join('\n'),
413			sentences.map((x) => x.fromName).join('\n')
414		);
415	
416		const born = compareYear(inscription.born, stated.born, stated.bornSlack);
417		const died = compareYear(inscription.died, stated.died, 0);
418		const all = statedYears(text, text);
419		return {
420			name: true,
421			born,
422			died,
423			bornYear: reportedYear(inscription.born, stated.born, stated.bornSlack),
424			diedYear: reportedYear(inscription.died, stated.died, 0),
425			stated: { born: stated.born, died: stated.died, slack: stated.bornSlack },
426			statesOther:
427				compareYear(inscription.born, all.born, all.bornSlack) === 'conflict' ||
428				compareYear(inscription.died, all.died, 0) === 'conflict'
429		};
430	}
431	
432	/**
433	 * Grades a fetched page as evidence for the stone's person, on the same keys as a search result.
434	 * @param inscription The stone's person.
435	 * @param text The page's text.
436	 * @returns The grade, or null when the page lacks the name or states a year against the stone.
437	 */
438	export function gradePage(inscription: Inscription, text: string): Confidence | null {
439		const e = weigh(inscription, { id: '', url: '', title: '', site: '', snippet: text });
440		if (!e.name || e.born === 'conflict' || e.died === 'conflict') return null;
441		return rate(1 + Number(e.born === 'match') + Number(e.died === 'match'), keysOf(inscription));
442	}
443	
444	/**
445	 * Whether a page states a birth or death year for the name that the stone contradicts.
446	 * @param inscription The stone's person.
447	 * @param text The page's text.
448	 * @returns True when a year stated beside the name disagrees with the stone.
449	 */
450	export function statesOtherDates(inscription: Inscription, text: string): boolean {
451		const e = weigh(inscription, { id: '', url: '', title: '', site: '', snippet: text });
452		return e.born === 'conflict' || e.died === 'conflict';
453	}
454	
455	/**
456	 * Counts the keys a stone offers for matching.
457	 * @param inscription The stone's person.
458	 * @returns Its name plus each date it carries.
459	 */
460	function keysOf(inscription: Inscription): number {
461		return 1 + Number(!!inscription.born) + Number(!!inscription.died);
462	}
463	
464	/**
465	 * Rates the match from how many of the stone's keys the evidence confirms.
466	 * @param matched Keys confirmed, counting the name.
467	 * @param available Keys the stone offers: its name plus each date it carries.
468	 * @returns High when every available key matches, medium for two or more, else low.
469	 */
470	function rate(matched: number, available: number): Confidence {
471		if (matched >= 2 && matched === available) return 'high';
472		return matched >= 2 ? 'medium' : 'low';
473	}
474	
475	/**
476	 * Whether two stated years contradict each other.
477	 * @param x First year, or null when not stated.
478	 * @param y Second year, or null when not stated.
479	 * @param slackX Years the true first year may lie before `x`.
480	 * @param slackY Years the true second year may lie before `y`.
481	 * @returns True only when both are stated and their intervals do not overlap.
482	 */
483	function yearsDiffer(x: number | null, y: number | null, slackX: number, slackY: number): boolean {
484		return x !== null && y !== null && (x - y > slackX || y - x > slackY);
485	}
486	
487	/**
488	 * Whether two results can describe one person: no stated year of one contradicts the other.
489	 * @param a Evidence of one result.
490	 * @param b Evidence of another result.
491	 * @returns False when both state a birth or death year and the years differ.
492	 */
493	function sameDates(a: Evidence, b: Evidence): boolean {
494		return (
495			!yearsDiffer(a.stated.born, b.stated.born, a.stated.slack, b.stated.slack) &&
496			!yearsDiffer(a.stated.died, b.stated.died, 0, 0)
497		);
498	}
499	
500	/** A result with its evidence and how many of the stone's keys it confirms. */
501	interface Scored {
502		record: SourceRecord;
503		e: Evidence;
504		score: number;
505	}
506	
507	/**
508	 * Builds a candidate from results that agree with each other.
509	 * @param inscription The stone's person.
510	 * @param group Results about one person, best first.
511	 * @returns The candidate.
512	 */
513	function candidateOf(inscription: Inscription, group: Scored[]): Candidate {
514		const kept = group.slice(0, MAX_SOURCES);
515		return {
516			name: inscription.name,
517			born: kept.find((s) => s.e.bornYear)?.e.bornYear ?? null,
518			died: kept.find((s) => s.e.diedYear)?.e.diedYear ?? null,
519			confidence: rate(Math.max(...kept.map((s) => s.score)), keysOf(inscription)),
520			sources: kept.map((s) => s.record)
521		};
522	}
523	
524	/**
525	 * Finds the search results that are about the stone's person.
526	 *
527	 * Name, birth year and death year are the keys. A result with the name and at least one matching
528	 * date is returned even when its other date is missing. A stated year that disagrees with the
529	 * stone excludes the result. When nothing confirms a date, name-only results are returned as
530	 * unverified, but only those that state no year against the stone anywhere.
531	 * Results whose stated dates contradict each other are different people, so they become separate
532	 * candidates rather than being merged.
533	 * @param inscription The stone's person.
534	 * @param records Deduplicated search results.
535	 * @returns Up to three candidates, best first: most keys matched, then most agreeing results,
536	 *   then search rank. None when nothing matches.
537	 */
538	export function resolveMatches(inscription: Inscription, records: SourceRecord[]): Candidate[] {
539		const scored: Scored[] = records
540			.map((record) => ({ record, e: weigh(inscription, record) }))
541			.filter(({ e }) => e.name && e.born !== 'conflict' && e.died !== 'conflict')
542			.map(({ record, e }) => ({
543				record,
544				e,
545				score: 1 + Number(e.born === 'match') + Number(e.died === 'match')
546			}))
547			// Nothing else ties a name-only result to the stone, so any date it gives against the stone
548			// marks a namesake.
549			.filter((s) => s.score >= 2 || !s.e.statesOther);
550		const best = Math.max(0, ...scored.map((s) => s.score));
551		if (!best) return [];
552		const ranked = scored
553			.filter((s) => (best >= 2 ? s.score >= 2 : s.score === 1))
554			.sort((a, b) => b.score - a.score);
555		const groups: Scored[][] = [];
556		for (const s of ranked) {
557			const home = groups.find((g) => g.every((m) => sameDates(m.e, s.e)));
558			if (home) home.push(s);
559			else groups.push([s]);
560		}
561		// The app tells the first candidate without asking, so a tie goes to the person more results
562		// agree on; a stable sort keeps search rank after that.
563		groups.sort((a, b) => b[0].score - a[0].score || b.length - a.length);
564		return groups.slice(0, MAX_CANDIDATES).map((g) => candidateOf(inscription, g));
565	}
