  1	// Research benchmark: runs the real research workflow for every reviewed fixture person and saves
  2	// the candidates as a new benchmarks/results/research-N.json. SerpApi replays the raw responses in
  3	// fixtures/serp/, so a run costs nothing. RECORD=1 sends a search with no saved response to SerpApi
  4	// (one credit each) and saves it, along with any Google redirect it follows (free). NO_PLACE=1 runs
  5	// without the fixtures' towns; FIXTURES=people runs only people.json.
  6	// Run with `pnpm eval benchmarks/research.eval.ts`.
  7	import { createHash } from 'node:crypto';
  8	import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
  9	import { afterAll, describe, expect, it, vi } from 'vitest';
 10	import { normalizeInscriptions } from '../src/lib/server/inscription.ts';
 11	import { runResearch } from '../src/lib/server/research.ts';
 12	
 13	interface Fixture {
 14		file: string;
 15		reviewed: boolean;
 16		place: string | null;
 17		people: { name: string; born: string | null; died: string | null }[];
 18	}
 19	
 20	const { env } = vi.hoisted(() => {
 21		process.loadEnvFile('.env');
 22		return { env: { SERPAPI_API_KEY: process.env.SERPAPI_API_KEY } };
 23	});
 24	vi.mock('$app/env/private', () => env);
 25	
 26	const SAVED = 'fixtures/serp';
 27	const RECORD = process.env.RECORD === '1';
 28	const WITH_PLACE = process.env.NO_PLACE !== '1';
 29	const live = globalThis.fetch;
 30	// Searches each person's run made, and searches with no saved response in replay mode.
 31	let ran: string[] = [];
 32	const missing = new Set<string>();
 33	let recorded = 0;
 34	
 35	/**
 36	 * Removes the API key from a SerpApi response before it is saved.
 37	 * @param value Parsed response, or part of one.
 38	 * @returns The value without any `api_key` field.
 39	 */
 40	function scrub(value: unknown): unknown {
 41		if (Array.isArray(value)) return value.map(scrub);
 42		if (!value || typeof value !== 'object') return value;
 43		return Object.fromEntries(
 44			Object.entries(value)
 45				.filter(([k]) => k !== 'api_key')
 46				.map(([k, v]) => [k, scrub(v)])
 47		);
 48	}
 49	
 50	/**
 51	 * Answers a Google redirect hop from its saved location, recording it when RECORD=1.
 52	 * @param url Redirect URL.
 53	 * @param init Request options.
 54	 * @returns The saved or live redirect.
 55	 */
 56	async function hop(url: URL, init?: RequestInit): Promise<Response> {
 57		const id = createHash('sha256').update(url.href).digest('hex').slice(0, 16);
 58		const file = `${SAVED}/goto-${id}.json`;
 59		if (!existsSync(file) && !RECORD) {
 60			missing.add(`goto: ${url.href}`);
 61			return new Response(null, { status: 599 });
 62		}
 63		if (!existsSync(file)) {
 64			const res = await live(url, init);
 65			const saved = { url: url.href, status: res.status, location: res.headers.get('location') };
 66			writeFileSync(file, `${JSON.stringify(saved, null, '\t')}\n`);
 67			recorded++;
 68		}
 69		const { status, location } = JSON.parse(readFileSync(file, 'utf8'));
 70		return new Response(null, { status, headers: location ? { location } : {} });
 71	}
 72	
 73	/**
 74	 * Answers SerpApi requests from saved responses, recording new ones when RECORD=1.
 75	 * @param input Request URL.
 76	 * @param init Request options.
 77	 * @returns The saved or live response.
 78	 */
 79	async function replay(input: string | URL | Request, init?: RequestInit): Promise<Response> {
 80		const url = new URL(input instanceof Request ? input.url : String(input));
 81		if (url.host === 'www.google.com') return hop(url, init);
 82		if (url.host !== 'serpapi.com') return live(input, init);
 83		url.searchParams.delete('api_key');
 84		url.searchParams.sort();
 85		const engine = url.searchParams.get('engine');
 86		const query = url.searchParams.get('q') ?? url.searchParams.get('text');
 87		ran.push(`${engine}: ${query}`);
 88		const id = createHash('sha256').update(url.search).digest('hex').slice(0, 16);
 89		const file = `${SAVED}/${engine}-${id}.json`;
 90		if (existsSync(file)) {
 91			const saved = JSON.parse(readFileSync(file, 'utf8'));
 92			return Response.json(saved.body, { status: saved.status });
 93		}
 94		if (!RECORD) {
 95			missing.add(`${engine}: ${query}`);
 96			return Response.json({ error: 'not recorded' }, { status: 599 });
 97		}
 98		let status: number;
 99		let body: unknown;
100		try {
101			const res = await live(input, init);
102			status = res.status;
103			body = scrub(await res.json());
104		} catch (e) {
105			// A search SerpApi never answers is saved too, so a replay takes the same fallback path.
106			status = 504;
107			body = { error: `Not answered while recording: ${(e as Error).name}` };
108		}
109		const text = JSON.stringify({ engine, query, status, body }, null, '\t');
110		// A saved response must never carry the key, whatever SerpApi echoes back.
111		if (env.SERPAPI_API_KEY && text.includes(env.SERPAPI_API_KEY)) throw new Error('key in response');
112		mkdirSync(SAVED, { recursive: true });
113		writeFileSync(file, `${text}\n`);
114		recorded++;
115		return Response.json(body, { status });
116	}
117	vi.stubGlobal('fetch', replay);
118	
119	/**
120	 * Reads a fixture file.
121	 * @param path File relative to the repo root.
122	 * @returns Its fixtures.
123	 */
124	const load = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as Fixture[];
125	// Photo fixtures count once reviewed; people.json cases carry no photo and are labeled per row.
126	// FIXTURES=people runs only the people.json cases, whose own memorial is known.
127	const fixtures = [
128		...(process.env.FIXTURES === 'people'
129			? []
130			: load('fixtures/manifest.json').filter((f) => f.reviewed)),
131		...load('fixtures/people.json')
132	];
133	/**
134	 * Names a labeled place the way the app's geocoder does: town and state, the county only when no town
135	 * is known.
136	 * @param place Label such as "Eugene, Lane County, Oregon".
137	 * @returns The place as research receives it, such as "Eugene, Oregon".
138	 */
139	function asGeocoded(place: string | null): string | null {
140		const parts = place?.split(', ') ?? [];
141		return parts.length === 3 ? `${parts[0]}, ${parts[2]}` : (place ?? null);
142	}
143	
144	const rows: unknown[] = [];
145	
146	describe('research', () => {
147		it.each(fixtures.flatMap((f) => f.people.map((p) => [`${f.file} ${p.name}`, f, p] as const)))(
148			'%s',
149			async (_, fixture, person) => {
150				ran = [];
151				// Normalized as the app does. The voice stays empty so the story eval checks the voice the
152				// records give, not the label.
153				const [inscription] = normalizeInscriptions([
154					{ ...person, voice: null, place: WITH_PLACE ? asGeocoded(fixture.place) : null }
155				]);
156				const candidates = await runResearch(inscription);
157				rows.push({
158					file: fixture.file,
159					reviewed: fixture.reviewed,
160					person,
161					inscription,
162					searches: ran,
163					candidates
164				});
165				expect(candidates).toBeInstanceOf(Array);
166			},
167			// Up to six live searches run one after another while recording.
168			120_000
169		);
170	});
171	
172	afterAll(() => {
173		const runs = readdirSync('benchmarks/results')
174			.map((f) => /^research-(\d+)\.json$/.exec(f)?.[1])
175			.filter(Boolean)
176			.map(Number);
177		const out = `benchmarks/results/research-${Math.max(0, ...runs) + 1}.json`;
178		const meta = {
179			startedAt: new Date().toISOString(),
180			withPlace: WITH_PLACE,
181			recorded,
182			missing: [...missing]
183		};
184		writeFileSync(out, `${JSON.stringify({ meta, rows }, null, '\t')}\n`);
185		console.log(
186			`${out}: ${rows.length} people, ${recorded} searches recorded, ${missing.size} missing`
187		);
188		expect([...missing]).toEqual([]);
189	});
  1	// Live eval: tells a story for every case on the real model and judges it. Page fetches replay the
  2	// fixtures, so only the model calls are live. Run with `pnpm eval`.
  3	// - stories-written.json: hand-written records that bait specific failures, always the right person.
  4	// - stories-recorded.json: real search results, which may describe someone else until labeled.
  5	import { afterAll, describe, expect, it, vi } from 'vitest';
  6	import { epitaph } from '../../src/lib/epitaph.ts';
  7	import { runStoneStory, runStory } from '../../src/lib/server/story.ts';
  8	import type { Candidate, Inscription, Voice } from '../../src/lib/types.ts';
  9	import { lifeClaimsScorer } from './life-claims.ts';
 10	import { ageAtDeath, yearsOutsideLife } from './stone-years.ts';
 11	
 12	interface StoryCase {
 13		inscription: Inscription;
 14		candidates: Candidate[];
 15		pages: Record<string, string | null>;
 16		match: number | null;
 17		reviewed: boolean;
 18		/** The narrator the person should get, whatever the name suggests. */
 19		voice: Voice;
 20		/** Hand-written stories that check the graders: `good` must pass, `bad` must fail. */
 21		good?: string;
 22		bad?: string;
 23	}
 24	
 25	// Hoisted above the imports, so node:fs is reached without one.
 26	const { sets, env } = vi.hoisted(() => {
 27		const { readFileSync } = process.getBuiltinModule('node:fs');
 28		process.loadEnvFile('.env');
 29		/**
 30		 * Reads one fixture set.
 31		 * @param path Fixture file, relative to the repo root.
 32		 * @returns Its cases.
 33		 */
 34		const load = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as StoryCase[];
 35		return {
 36			sets: {
 37				written: load('fixtures/stories-written.json'),
 38				recorded: load('fixtures/stories-recorded.json')
 39			},
 40			env: { GEMINI_API_KEY: process.env.GEMINI_API_KEY }
 41		};
 42	});
 43	vi.mock('$app/env/private', () => env);
 44	vi.mock('../../src/lib/server/pages.ts', () => ({
 45		fetchPage: async (url: string) =>
 46			[...sets.written, ...sets.recorded].find((c) => url in c.pages)?.pages[url] ?? null
 47	}));
 48	
 49	const scorer = lifeClaimsScorer(env.GEMINI_API_KEY ?? '');
 50	const timings: number[] = [];
 51	// Trial outcomes per set and person, for pass@1 (share of trials) and pass^3 (every trial).
 52	const trials = new Map<string, Map<string, boolean[]>>();
 53	// Narrator picks per set, kept apart from story trials so a wrong voice does not hide in them.
 54	const voices = new Map<string, boolean[]>();
 55	// The story model samples at temperature 1, so one passing draw proves little. A case passes only
 56	// when every draw does.
 57	const SAMPLES = 3;
 58	
 59	/**
 60	 * Picks the candidate the story is told about: the labeled match, else the top hit.
 61	 * @param c Recorded case.
 62	 * @returns The candidate, or undefined when research found none or none is the person.
 63	 */
 64	function told(c: StoryCase): Candidate | undefined {
 65		return c.match === -1 ? undefined : c.candidates[c.match ?? 0];
 66	}
 67	
 68	/**
 69	 * Runs both graders on one paragraph.
 70	 * @param c The case.
 71	 * @param paragraph The story to grade.
 72	 * @param fromRecords Whether the story was told from the candidate's records or the stone alone.
 73	 * @returns Years outside the stone's life, the judge's score, and its reasons.
 74	 */
 75	async function grade(
 76		c: StoryCase,
 77		paragraph: string,
 78		fromRecords: boolean
 79	): Promise<{ years: number[]; score: number; reason: string }> {
 80		const age = ageAtDeath(c.inscription);
 81		const stone = [...epitaph(c.inscription, new Date()), ...(age ? [age] : [])];
 82		// Every source of the candidate counts, not just those cited: a true claim is never a failure.
 83		const records = fromRecords ? told(c)!.sources.map((s) => c.pages[s.url] ?? s.snippet) : [];
 84		const result = await scorer.run({
 85			input: { subject: c.inscription.name, context: [...stone, ...records] },
 86			output: paragraph
 87		});
 88		return {
 89			years: yearsOutsideLife(paragraph, c.inscription),
 90			// A run the scorer could not score counts as a failure.
 91			score: result.score ?? 0,
 92			reason: result.reason ?? ''
 93		};
 94	}
 95	
 96	describe.each(Object.entries(sets))('%s stories', (set, cases) => {
 97		it.each(cases.filter((c) => c.good && c.bad).map((c) => [c.inscription.name, c] as const))(
 98			'%s: graders pass the good reference and fail the bad one',
 99			async (_, c) => {
100				const good = await grade(c, c.good!, true);
101				expect.soft(good, `good reference\n${good.reason}`).toMatchObject({ years: [], score: 1 });
102				const bad = await grade(c, c.bad!, true);
103				expect.soft(bad.score, `bad reference\n${bad.reason}`).toBeLessThan(1);
104			},
105			120_000
106		);
107	
108		it.each(
109			cases.flatMap((c) =>
110				Array.from({ length: SAMPLES }, (_, i) => [c.inscription.name, i + 1, c] as const)
111			)
112		)(
113			'%s #%i: every life claim is in the records and fits the stone',
114			async (name, __, c) => {
115				const candidate = told(c);
116				const t0 = performance.now();
117				const story = candidate
118					? await runStory(c.inscription, candidate)
119					: await runStoneStory(c.inscription);
120				timings.push(performance.now() - t0);
121	
122				expect(story.paragraph, 'the story must always be told').toBeTruthy();
123				const { years, score, reason } = await grade(
124					c,
125					story.paragraph ?? '',
126					story.status === 'told'
127				);
128				const byName = trials.get(set) ?? new Map<string, boolean[]>();
129				trials.set(
130					set,
131					byName.set(name, [...(byName.get(name) ?? []), !years.length && score === 1])
132				);
133				voices.set(set, [...(voices.get(set) ?? []), story.voice === c.voice]);
134				expect.soft(story.voice, 'narrator voice').toBe(c.voice);
135				expect.soft(years, `years outside the stone's life\n${story.paragraph}`).toEqual([]);
136				expect.soft(score, `${story.paragraph}\n\n${reason}`).toBe(1);
137			},
138			180_000
139		);
140	});
141	
142	afterAll(() => {
143		const s = [...timings].sort((a, b) => a - b);
144		console.log(`story median ${Math.round(s[Math.floor(s.length / 2)] ?? 0)} ms over ${s.length}`);
145		for (const [set, byName] of trials) {
146			const all = [...byName.values()];
147			const passed = all.flat().filter(Boolean).length;
148			const picks = voices.get(set) ?? [];
149			console.log(`${set}: voice ${picks.filter(Boolean).length}/${picks.length}`);
150			console.log(
151				`${set}: pass@1 ${passed}/${all.flat().length}, pass^${SAMPLES} ${all.filter((t) => t.every(Boolean)).length}/${all.length}`
152			);
153		}
154	});
  1	import { createScorer } from '@mastra/core/evals';
  2	import { z } from 'zod';
  3	
  4	const JUDGE_MODEL = 'google/gemini-3.8-flash';
  5	
  6	/** What the story was written from: the person's name and every true text about them. */
  7	export interface LifeClaimsInput {
  8		subject: string;
  9		context: string[];
 10	}
 11	
 12	const claimSchema = z.object({
 13		claim: z.string().describe('One claim, restated in plain words.'),
 14		kind: z.enum(['life', 'atmosphere', 'unsure']),
 15		evidence: z
 16			.string()
 17			.nullable()
 18			.describe('Exact words copied from the records that support the claim; null when none do.')
 19	});
 20	
 21	export type Claim = z.infer<typeof claimSchema>;
 22	
 23	const JUDGE_INSTRUCTIONS = `<role>You audit a ghost story told at a grave for claims about a real person's life that the records do not support.</role>
 24	
 25	<how_you_work>
 26	- Split the story into every claim it makes, one per item. A sentence can hold several.
 27	- kind "life": anything about the real person while alive: names, dates, ages, places, family, relationships, work, events, possessions, habits, traits, memories, and feelings about any of those.
 28	- kind "atmosphere": the openly fictional frame: being a ghost, the grave, the dark, the weather, the visitor, the present moment, the afterlife.
 29	- A claim that dresses a life detail in otherworld words is "life". "From beyond I watched my children grow" claims children.
 30	- What is true of every dead person is "atmosphere": they lived, breathed, were born, died, and time has passed since. "I once breathed where you stand" claims nothing.
 31	- How the life or death went is "life", and it holds when the records imply it. Died at 96: "a long life" holds. Died at 19: "gone too soon" holds. An organ donor: "pieces of me live on" holds. Died at 45: "a long life" is false.
 32	- kind "unsure": you cannot tell whether the claim says something about the life. Use it instead of guessing.
 33	- evidence: copy the exact words from the records that state the claim, or that it follows from directly. Copy, do not paraphrase.
 34	</how_you_work>
 35	
 36	<never>
 37	- Never mark a claim "atmosphere" because it is poetic.
 38	- Never give evidence that only makes a claim plausible. It must state the claim or prove it.
 39	</never>`;
 40	
 41	/**
 42	 * Lowercases, drops replacement characters and collapses everything else but letters and digits
 43	 * to single spaces.
 44	 * @param s Text to normalize.
 45	 * @returns Normalized text.
 46	 */
 47	function norm(s: string): string {
 48		return (
 49			s
 50				// Pages decoded with the wrong charset carry U+FFFD mid-word ("60�s"); the judge drops it.
 51				.replaceAll('\uFFFD', '')
 52				.toLowerCase()
 53				.replace(/[^\p{L}\p{N}]+/gu, ' ')
 54				.trim()
 55		);
 56	}
 57	
 58	/**
 59	 * Finds claims that fail: every claim the judge was unsure of, and life claims whose evidence is
 60	 * missing or not found word for word in the records. The judge names the evidence; this check keeps
 61	 * it from vouching for words the records do not contain.
 62	 * @param claims Claims the judge extracted.
 63	 * @param context Records the story may draw on.
 64	 * @returns Claims that needed support and the subset that failed.
 65	 */
 66	export function auditClaims(
 67		claims: Claim[],
 68		context: string[]
 69	): { checked: Claim[]; unsupported: Claim[] } {
 70		const records = ` ${context.map(norm).join(' | ')} `;
 71		const checked = claims.filter((c) => c.kind !== 'atmosphere');
 72		const unsupported = checked.filter((c) => {
 73			const evidence = norm(c.evidence ?? '');
 74			return c.kind === 'unsure' || !evidence || !records.includes(` ${evidence} `);
 75		});
 76		return { checked, unsupported };
 77	}
 78	
 79	/**
 80	 * Builds the scorer for life claims in a told story.
 81	 * @param apiKey Gemini API key for the judge.
 82	 * @returns A scorer: the share of checked claims backed by the records, 1 when the story makes none.
 83	 */
 84	export function lifeClaimsScorer(apiKey: string) {
 85		return createScorer<LifeClaimsInput, string>({
 86			id: 'life-claims',
 87			description: 'Every claim about the life of the person must be stated in the records.',
 88			judge: {
 89				model: { id: JUDGE_MODEL, apiKey },
 90				instructions: JUDGE_INSTRUCTIONS,
 91				modelSettings: { temperature: 0 }
 92			}
 93		})
 94			.analyze({
 95				description: 'Extract claims and the record text that supports each',
 96				outputSchema: z.object({ claims: z.array(claimSchema) }),
 97				createPrompt: ({ run }) =>
 98					`<records>\n${run.input!.context.join('\n---\n')}\n</records>\n\n<story subject="${run.input!.subject}">\n${run.output}\n</story>\n\nBased on the records above, list every claim the story makes.`
 99			})
100			.generateScore(({ run, results }) => {
101				const { checked, unsupported } = auditClaims(
102					results.analyzeStepResult.claims,
103					run.input!.context
104				);
105				return checked.length ? (checked.length - unsupported.length) / checked.length : 1;
106			})
107			.generateReason(({ run, results }) =>
108				auditClaims(results.analyzeStepResult.claims, run.input!.context)
109					.unsupported.map((c) => `${c.kind}: ${c.claim} (evidence: ${c.evidence ?? 'none'})`)
110					.join('\n')
111			);
112	}
  1	import type { Inscription } from '../../src/lib/types.ts';
  2	
  3	/**
  4	 * Reads the whole year out of a stone date.
  5	 * @param date Partial date as normalized, e.g. `1943-07-11`, `1943` or `19?3`.
  6	 * @returns The year, or null when absent or not fully legible.
  7	 */
  8	function year(date: string | null): number | null {
  9		const y = date?.slice(0, 4) ?? '';
 10		return /^\d{4}$/.test(y) ? Number(y) : null;
 11	}
 12	
 13	/**
 14	 * Finds years in a story that fall outside the life the stone records. The stone is the one source
 15	 * known to be about this person, so a year before birth or after death means the records describe
 16	 * someone else.
 17	 * @param paragraph The story as told.
 18	 * @param inscription The stone's person.
 19	 * @param today Current date; a number past this year is a house number, not a year.
 20	 * @returns Offending years, in order of appearance.
 21	 */
 22	export function yearsOutsideLife(
 23		paragraph: string,
 24		inscription: Inscription,
 25		today = new Date()
 26	): number[] {
 27		const born = year(inscription.born) ?? -Infinity;
 28		const died = year(inscription.died) ?? Infinity;
 29		return [...paragraph.matchAll(/\b\d{4}\b/g)]
 30			.map((m) => Number(m[0]))
 31			.filter((y) => y <= today.getUTCFullYear() && (y < born || y > died));
 32	}
 33	
 34	/**
 35	 * States the age at death the stone's dates prove, so a story may call the life long or short.
 36	 * @param inscription The stone's person.
 37	 * @returns A sentence, or null when either year is missing or not fully legible.
 38	 */
 39	export function ageAtDeath(inscription: Inscription): string | null {
 40		const born = year(inscription.born);
 41		const died = year(inscription.died);
 42		if (born === null || died === null) return null;
 43		// Without both full dates the birthday may not have come yet in the year of death.
 44		const exact = inscription.born!.length === 10 && inscription.died!.length === 10;
 45		const age =
 46			died - born - Number(exact && inscription.died!.slice(5) < inscription.born!.slice(5));
 47		return exact ? `I died at ${age} years old.` : `I died at about ${age} years old.`;
 48	}

