     2	// Lists every search result each person's research run saw, from the saved SerpApi responses, with
     3	// what the identity engine did with it and why. Saves benchmarks/results/sources-N.json for labeling:
     4	// `right` is null until the user marks a result true (the stone's person) or false (someone else).
     5	// A people.json case's own memorial is the one result known to be right before labeling.
     6	import { createHash } from 'node:crypto';
     7	import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
     8	import { dropGated, gradePage, resolveMatches } from '../src/lib/server/identity.ts';
     9	import { canonicalUrl } from '../src/lib/server/search/url.ts';
    10	import type { Candidate, Inscription, SourceRecord } from '../src/lib/types.ts';
    11	
    12	interface Row {
    13		file: string;
    14		inscription: Inscription;
    15		searches: string[];
    16		candidates: Candidate[];
    17	}
    18	
    19	type Verdict =
    20		| 'kept'
    21		| 'gated site'
    22		| 'no name or another initial'
    23		| 'date against stone'
    24		| 'weaker than a dated match'
    25		| 'over five sources';
    26	
    27	const SAVED = 'fixtures/serp';
    28	const RESULTS = 'benchmarks/results';
    29	/**
    30	 * Finds the highest run number saved under a result prefix.
    31	 * @param prefix File prefix such as "research".
    32	 * @returns The number, or 0 when none is saved.
    33	 */
    34	const newest = (prefix: string) =>
    35		Math.max(
    36			0,
    37			...readdirSync(RESULTS)
    38				.map((f) => new RegExp(`^${prefix}-(\\d+)\\.json$`).exec(f)?.[1])
    39				.filter(Boolean)
    40				.map(Number)
    41		);
    42	const runFile = process.argv[2] ?? `${RESULTS}/research-${newest('research')}.json`;
    43	const run = JSON.parse(readFileSync(runFile, 'utf8')) as { rows: Row[] };
    44	
    45	const responses = new Map<string, { body?: { organic_results?: Record<string, string>[] } }>();
    46	for (const f of readdirSync(SAVED).filter((x) => !x.startsWith('goto-'))) {
    47		const saved = JSON.parse(readFileSync(`${SAVED}/${f}`, 'utf8'));
    48		responses.set(`${saved.engine}: ${saved.query}`, saved);
    49	}
    50	const truth = new Map<string, string>(
    51		JSON.parse(readFileSync('fixtures/people.json', 'utf8')).map(
    52			(p: { file: string; source: string }) => [p.file, canonicalUrl(p.source)]
    53		)
    54	);
    55	const pages = new Map<string, string | null>(
    56		JSON.parse(readFileSync('fixtures/stories-recorded.json', 'utf8')).flatMap(
    57			(c: { pages: Record<string, string | null> }) => Object.entries(c.pages)
    58		)
    59	);
    60	
    61	/**
    62	 * Resolves a Google redirect link from its saved hop.
    63	 * @param link Result link.
    64	 * @returns The page it leads to, or null.
    65	 */
    66	function page(link = ''): string | null {
    67		if (/^https?:/.test(link) && !link.includes('google.com/goto')) return link;
    68		const href = new URL(link, 'https://www.google.com').href;
    69		const file = `${SAVED}/goto-${createHash('sha256').update(href).digest('hex').slice(0, 16)}.json`;
    70		return existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')).location : null;
    71	}
    72	
    73	const people = run.rows.map((row) => {
    74		const ins = row.inscription;
    75		const kept = new Set(row.candidates.flatMap((c) => c.sources.map((s) => canonicalUrl(s.url))));
    76		const dated = row.candidates.some((c) => c.confidence !== 'low');
    77		const hits = new Map<string, SourceRecord & { search: string }>();
    78		for (const search of new Set(row.searches))
    79			for (const r of responses.get(search)?.body?.organic_results ?? []) {
    80				const url = page(r.link);
    81				const key = url && canonicalUrl(url);
    82				if (!key || hits.has(key)) continue;
    83				const site = URL.parse(url)!.hostname;
    84				hits.set(key, { id: '', url, title: r.title ?? '', site, snippet: r.snippet ?? '', search });
    85			}
    86		const results = [...hits.entries()].map(([key, hit]) => {
    87			const alone = resolveMatches(ins, [hit])[0];
    88			const undated = resolveMatches({ ...ins, born: null, died: null }, [hit]).length > 0;
    89			let verdict: Verdict = 'kept';
    90			if (!kept.has(key)) {
    91				if (!dropGated([hit]).length) verdict = 'gated site';
    92				else if (!alone) verdict = undated ? 'date against stone' : 'no name or another initial';
    93				else if (dated && alone.confidence === 'low') verdict = 'weaker than a dated match';
    94				else verdict = 'over five sources';
    95			}
    96			const text = pages.get(hit.url);
    97			return {
    98				url: hit.url,
    99				search: hit.search.split(':')[0],
   100				query: hit.search.slice(hit.search.indexOf(':') + 2),
   101				title: hit.title,
   102				snippet: hit.snippet,
   103				grade: alone?.confidence ?? null,
   104				verdict,
   105				// What the fetched page proves, for kept results only: the story fetches nothing else.
   106				page:
   107					text === undefined
   108						? null
   109						: text === null
   110							? 'unreadable'
   111							: (gradePage(ins, text) ?? 'against or unnamed'),
   112				right: truth.get(row.file) === key ? true : null
   113			};
   114		});
   115		return { file: row.file, name: ins.name, born: ins.born, died: ins.died, results };
   116	});
   117	
   118	const out = `${RESULTS}/sources-${newest('sources') + 1}.json`;
   119	writeFileSync(out, `${JSON.stringify({ run: runFile, people }, null, '\t')}\n`);
   120	
   121	const all = people.flatMap((p) => p.results);
   122	/**
   123	 * Counts results.
   124	 * @param pick Which results to count.
   125	 * @returns How many match.
   126	 */
   127	const count = (pick: (r: (typeof all)[number]) => boolean) => all.filter(pick).length;
   128	console.log(`${out}: ${all.length} results for ${people.length} people from ${runFile}`);
   129	for (const v of [
   130		'kept',
   131		'gated site',
   132		'no name or another initial',
   133		'date against stone',
   134		'weaker than a dated match',
   135		'over five sources'
   136	])
   137		console.log(`  ${v.padEnd(26)} ${count((r) => r.verdict === v)}`);
   138	for (const p of people.filter((x) => truth.has(x.file))) {
   139		const own = p.results.find((r) => r.right);
   140		console.log(
   141			`  own memorial, ${p.name.padEnd(30)} ${own ? `${own.verdict} (${own.search})` : 'never returned'}`
   142		);
   143	}
     1	// Usage: node benchmarks/record-stories.ts [benchmarks/results/research-N.json]
     2	// Freezes story inputs for the evals from a research benchmark run (the newest by default), so no
     3	// search is sent: every candidate comes from SerpApi responses saved in fixtures/serp. Writes each
     4	// person's candidates with the text of their sources to fixtures/stories-recorded.json. A page saved
     5	// by an earlier recording is reused; only new pages are fetched, or every page with REFETCH=1.
     6	// Labels start unreviewed: `match` is null until the user sets the index of the candidate who is
     7	// the person on the stone, or -1 when none is. A label survives only while its candidates are unchanged.
     8	import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
     9	import { fetchPage } from '../src/lib/server/pages.ts';
    10	import type { Candidate, Inscription, Voice } from '../src/lib/types.ts';
    11	
    12	interface Row {
    13		file: string;
    14		person: { voice: Voice };
    15		inscription: Inscription;
    16		candidates: Candidate[];
    17	}
    18	
    19	interface StoryCase {
    20		file: string;
    21		inscription: Inscription;
    22		candidates: Candidate[];
    23		pages: Record<string, string | null>;
    24		match: number | null;
    25		reviewed: false;
    26		voice: Voice;
    27	}
    28	
    29	const RESULTS = 'benchmarks/results';
    30	const OUT = 'fixtures/stories-recorded.json';
    31	const newest = readdirSync(RESULTS)
    32		.map((f) => /^research-(\d+)\.json$/.exec(f)?.[1])
    33		.filter(Boolean)
    34		.map(Number)
    35		.sort((a, b) => b - a)[0];
    36	const runFile = process.argv[2] ?? `${RESULTS}/research-${newest}.json`;
    37	const run = JSON.parse(readFileSync(runFile, 'utf8')) as {
    38		meta: { missing: string[] };
    39		rows: Row[];
    40	};
    41	if (run.meta.missing.length) throw new Error(`${runFile} ran without saved searches`);
    42	
    43	const earlier = JSON.parse(readFileSync(OUT, 'utf8')) as StoryCase[];
    44	// REFETCH=1 fetches every page again, for when text extraction changes.
    45	const saved = new Map(
    46		process.env.REFETCH === '1' ? [] : earlier.flatMap((c) => Object.entries(c.pages))
    47	);
    48	/**
    49	 * Keys a case by its fixture and person.
    50	 * @param c A recorded case or research row.
    51	 * @param c.file Fixture file.
    52	 * @param c.inscription The person.
    53	 * @returns The key.
    54	 */
    55	const key = (c: { file: string; inscription: Inscription }) =>
    56		`${c.file}|${c.inscription.carvedName}`;
    57	const labels = new Map(earlier.map((c) => [key(c), c]));
    58	
    59	const cases: StoryCase[] = [];
    60	for (const row of run.rows) {
    61		const urls = [...new Set(row.candidates.flatMap((c) => c.sources.map((s) => s.url)))];
    62		const pages = Object.fromEntries(
    63			await Promise.all(
    64				urls.map(async (u) => [u, saved.has(u) ? saved.get(u)! : await fetchPage(u)] as const)
    65			)
    66		);
    67		const before = labels.get(key(row));
    68		const same = JSON.stringify(before?.candidates) === JSON.stringify(row.candidates);
    69		cases.push({
    70			file: row.file,
    71			inscription: row.inscription,
    72			candidates: row.candidates,
    73			pages,
    74			match: same ? (before?.match ?? null) : null,
    75			reviewed: false,
    76			voice: row.person.voice
    77		});
    78		console.error(
    79			`${row.inscription.name.padEnd(32)} ${row.candidates.length} candidates, ${urls.length} pages`
    80		);
    81	}
    82	writeFileSync(OUT, `${JSON.stringify(cases, null, '\t')}\n`);
    83	console.error(`${OUT}: ${cases.length} cases from ${runFile}`);
