    34		.map(Number)
    35		.sort((a, b) => b - a)[0];
    36	const runFile = process.argv[2] ?? `${RESULTS}/research-${newest}.json`;
    37	const run = JSON.parse(readFileSync(runFile, 'utf8')) as {
    38		meta: { missing: string[] };
    39		rows: Row[];
    40	};
    41	if (run.meta.missing.length) throw new Error(`${runFile} ran without saved searches`);
    42	
    43	const earlier = JSON.parse(readFileSync(OUT, 'utf8')) as StoryCase[];
    44	// REFETCH=1 fetches every page again, for when text extraction changes.
    45	const saved = new Map(
    46		process.env.REFETCH === '1' ? [] : earlier.flatMap((c) => Object.entries(c.pages))
    47	);
    48	/**
    49	 * Keys a case by its fixture and person.
    50	 * @param c A recorded case or research row.
    51	 * @param c.file Fixture file.
    52	 * @param c.inscription The person.
    53	 * @returns The key.
    54	 */
    55	const key = (c: { file: string; inscription: Inscription }) =>
    56		`${c.file}|${c.inscription.carvedName}`;
    57	const labels = new Map(earlier.map((c) => [key(c), c]));
    58	
    59	const cases: StoryCase[] = [];
    60	for (const row of run.rows) {
    61		const urls = [...new Set(row.candidates.flatMap((c) => c.sources.map((s) => s.url)))];
    62		const pages = Object.fromEntries(
    63			await Promise.all(
    64				urls.map(async (u) => [u, saved.has(u) ? saved.get(u)! : await fetchPage(u)] as const)
    65			)
    66		);
    67		const before = labels.get(key(row));
    68		const same = JSON.stringify(before?.candidates) === JSON.stringify(row.candidates);
    69		cases.push({
    70			file: row.file,
    71			inscription: row.inscription,
    72			candidates: row.candidates,
    73			pages,
    74			match: same ? (before?.match ?? null) : null,
    75			reviewed: false,
    76			voice: row.person.voice
    77		});
    78		console.error(
    79			`${row.inscription.name.padEnd(32)} ${row.candidates.length} candidates, ${urls.length} pages`
    80		);
    81	}
    82	writeFileSync(OUT, `${JSON.stringify(cases, null, '\t')}\n`);
    83	console.error(`${OUT}: ${cases.length} cases from ${runFile}`);
